func (ctq *CiTypeQuery) loadAttributes(ctx context.Context, query *AttributeQuery, nodes []*CiType, init func(*CiType), assign func(*CiType, *Attribute)) error {
	ids := make([]uint64, 0, len(nodes))
	nodeids := make(map[uint64][]*CiType)
	for i := range nodes {
		fk := nodes[i].UniqueID
		if _, ok := nodeids[fk]; !ok {
			ids = append(ids, fk)
		}
		nodeids[fk] = append(nodeids[fk], nodes[i])
	}
	if len(ids) == 0 {
		return nil
	}
	query.Where(attribute.IDIn(ids...))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		nodes, ok := nodeids[n.ID]
		if !ok {
			return fmt.Errorf(`unexpected foreign-key "unique_id" returned %v`, n.ID)
		}
		for i := range nodes {
			assign(nodes[i], n)
		}
	}
	return nil
}
